def dfs(graph, start):
    if not 0 <= start < len(graph):
        raise ValueError("invalid start")
    seen = {start}
    stack = [start]
    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in reversed(graph[u]):
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return order

