def largest_island(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    labels = [[0] * cols for _ in range(rows)]
    sizes = {}
    for label, group in enumerate(components(grid), 1):
        sizes[label] = len(group)
        for r,c in group:
            labels[r][c] = label
    best = max(sizes.values(), default=0)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                continue
            adjacent = set()
            for dr,dc in DIRS:
                nr,nc = r+dr,c+dc
                if 0 <= nr < rows and 0 <= nc < cols and labels[nr][nc]:
                    adjacent.add(labels[nr][nc])
            best = max(best, 1 + sum(sizes[x] for x in adjacent))
    return best

