def ladder_length(begin, end, words):
    if begin == end:
        return 1
    remaining = {w for w in words if len(w) == len(begin)}
    if len(end) != len(begin) or end not in remaining:
        return 0
    remaining.discard(begin)
    queue = deque([(begin, 1)])
    while queue:
        word, length = queue.popleft()
        for i in range(len(word)):
            for ch in ascii_lowercase:
                if ch == word[i]:
                    continue
                nxt = word[:i] + ch + word[i+1:]
                if nxt not in remaining:
                    continue
                if nxt == end:
                    return length + 1
                remaining.remove(nxt)
                queue.append((nxt, length+1))
    return 0

