def redundant_directed(edges):
    if not edges:
        return []
    n = len(edges)
    incoming = {}
    first = second = None
    for i,(u,v) in enumerate(edges):
        if v in incoming:
            first, second = incoming[v], i
        else:
            incoming[v] = i
    dsu = DSU(n+1)
    for i,(u,v) in enumerate(edges):
        if i == second:
            continue
        if not dsu.union(u,v):
            return list(edges[first if second is not None else i])
    return list(edges[second]) if second is not None else []

