def prim(n, edges):
    if n == 0:
        return 0
    graph = [[] for _ in range(n)]
    for u,v,w in edges:
        graph[u].append((v,w))
        graph[v].append((u,w))
    seen = set()
    heap = [(0,0)]
    total = 0
    while heap:
        weight,u = heappop(heap)
        if u in seen:
            continue
        seen.add(u)
        total += weight
        for v,w in graph[u]:
            if v not in seen:
                heappush(heap,(w,v))
    if len(seen) != n:
        raise ValueError("graph is disconnected")
    return total

