def kruskal(n, edges):
    if n == 0:
        return 0
    dsu = DSU(n)
    total = chosen = 0
    for u,v,w in sorted(edges, key=lambda edge: edge[2]):
        if dsu.union(u,v):
            total += w
            chosen += 1
            if chosen == n-1:
                break
    if chosen != n-1:
        raise ValueError("graph is disconnected")
    return total

