def topological_sort(n, edges):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for u,v in edges:
        graph[u].append(v)
        indegree[v] += 1
    queue = deque(u for u in range(n) if indegree[u] == 0)
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if len(order) != n:
        raise ValueError("directed cycle")
    return order

