def dijkstra_dense(n, edges, source):
    if not 0 <= source < n:
        raise ValueError("invalid source")
    matrix = [[inf] * n for _ in range(n)]
    for u,v,w in edges:
        if w < 0:
            raise ValueError("Dijkstra requires nonnegative weights")
        matrix[u][v] = min(matrix[u][v],w)
    dist = [inf] * n
    dist[source] = 0
    fixed = [False] * n
    for _ in range(n):
        u = -1
        for v in range(n):
            if not fixed[v] and (u == -1 or dist[v] < dist[u]):
                u = v
        if u == -1 or dist[u] == inf:
            break
        fixed[u] = True
        for v,w in enumerate(matrix[u]):
            if not fixed[v] and w != inf and dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
    return dist

