def dijkstra_heap(n, edges, source):
    if not 0 <= source < n:
        raise ValueError("invalid source")
    graph = [[] for _ in range(n)]
    for u,v,w in edges:
        if w < 0:
            raise ValueError("Dijkstra requires nonnegative weights")
        graph[u].append((v,w))
    dist = [inf] * n
    dist[source] = 0
    heap = [(0,source)]
    while heap:
        d,u = heappop(heap)
        if d != dist[u]:
            continue
        for v,w in graph[u]:
            candidate = d+w
            if candidate < dist[v]:
                dist[v] = candidate
                heappush(heap,(candidate,v))
    return dist

