def bellman_ford(n, edges, source):
    if not 0 <= source < n:
        raise ValueError("invalid source")
    dist = [inf] * n
    dist[source] = 0
    for _ in range(n-1):
        changed = False
        for u,v,w in edges:
            if dist[u] != inf and dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
                changed = True
        if not changed:
            break
    for u,v,w in edges:
        if dist[u] != inf and dist[u]+w < dist[v]:
            raise ValueError("reachable negative cycle")
    return dist

def has_negative_cycle(n, edges):
    dist = [0] * n
    for round_index in range(n):
        changed = False
        for u,v,w in edges:
            if dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
                changed = True
        if not changed:
            return False
        if round_index == n-1:
            return True
    return False

