def bounded_shortest_paths(n, edges, source, k):
    if k < 0 or not 0 <= source < n:
        raise ValueError("invalid source or edge budget")
    dist = [inf] * n
    dist[source] = 0
    for _ in range(k):
        old = dist
        dist = old.copy()
        for u,v,w in edges:
            if old[u] != inf and old[u]+w < dist[v]:
                dist[v] = old[u]+w
        if dist == old:
            break
    return dist

