def floyd_warshall(n, edges):
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u,v,w in edges:
        dist[u][v] = min(dist[u][v],w)
    for k in range(n):
        for i in range(n):
            if dist[i][k] == inf:
                continue
            for j in range(n):
                if dist[k][j] != inf:
                    dist[i][j] = min(dist[i][j], dist[i][k]+dist[k][j])
    if any(dist[v][v] < 0 for v in range(n)):
        raise ValueError("negative cycle")
    return dist

