def knight_distance(rows, cols, start, goal, blocked=()):
    blocked = set(blocked)
    def inside(p):
        return 0 <= p[0] < rows and 0 <= p[1] < cols
    if not inside(start) or not inside(goal):
        raise ValueError("position outside board")
    if start in blocked or goal in blocked:
        return -1
    def heuristic(p):
        dx,dy = abs(p[0]-goal[0]), abs(p[1]-goal[1])
        return max((dx+dy+2)//3, (max(dx,dy)+1)//2)
    moves = ((1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1))
    best = {start: 0}
    heap = [(heuristic(start),0,start)]
    while heap:
        _,g,p = heappop(heap)
        if g != best.get(p):
            continue
        if p == goal:
            return g
        for dr,dc in moves:
            nxt = (p[0]+dr,p[1]+dc)
            if inside(nxt) and nxt not in blocked and g+1 < best.get(nxt,float('inf')):
                best[nxt] = g+1
                heappush(heap,(g+1+heuristic(nxt),g+1,nxt))
    return -1

